pub fn remove_trailing_newline(value: String) -> String {
    value.trim_end().to_string()
}

pub fn read_from_stdin(text: &str) -> String {
    print_without_buffer(text);
    let mut result = String::new();
    io::stdin()
        .read_line(&mut result)
        .expect("Failed to read line");
    remove_trailing_newline(result)
}

pub fn simplify_config_path_for_display(dir: &Path) -> String {
    if !std::io::stdout().is_terminal() {
        return dir.display().to_string();
    }
    let base_dirs = BaseDirs::new().unwrap();
    let local_config_base_path = base_dirs.config_local_dir().to_str().unwrap();
    let mut display_config_path = dir.to_str().unwrap().to_string();
    display_config_path.replace_range(..local_config_base_path.len(), constants::SIMPLE_HOME_PATH);

    display_config_path
}

pub fn read_from_stdin_with_constraints(text: &str, valid_values: &[String]) -> String {
    loop {
        let result = read_from_stdin(text);
        if valid_values.contains(&result) {
            return result;
        } else {
            let error_message = format!(
                "Invalid value \"{}\". Valid values are: {}\n",
                result,
                valid_values.join(", ")
            )
            .red();
            print_without_buffer(&error_message);
        }
    }
}

pub fn open_path_in_editor<P>(path: P) -> ResultWithDefaultError<()>
where
    P: AsRef<Path> + std::convert::AsRef<std::ffi::OsStr>,
{
    let editor = std::env::var("EDITOR").unwrap_or_else(|_| "vim".to_string());
    let mut child = std::process::Command::new(editor)
        .arg(path)
        .spawn()
        .expect("Failed to spawn editor");
    child.wait().expect("Failed to wait for editor");
    Ok(())
}

pub fn get_git_branch_for_dir(dir: &PathBuf) -> Option<String> {
    let output = std::process::Command::new("git")
        .arg("branch")
        .arg("--show-current")
        .current_dir(dir)
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let branch = String::from_utf8(output.stdout).ok()?;
    Some(branch.trim().to_string())
}

pub fn parse_datetime_input(input: &str) -> ResultWithDefaultError<DateTime<Utc>> {
    let value = input.trim();
    if value.is_empty() {
        return Err(Box::new(ArgumentError::InvalidDateTime(input.to_string())));
    }

    // Natural language date/time keywords
    match value.to_lowercase().as_str() {
        "now" => return Ok(Utc::now()),
        "today" => {
            let today = Local::now().date_naive();
            let naive = today.and_hms_opt(0, 0, 0).unwrap();
            return match Local.from_local_datetime(&naive) {
                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
            };
        }
        "yesterday" => {
            let yesterday = Local::now().date_naive().pred_opt().unwrap();
            let naive = yesterday.and_hms_opt(0, 0, 0).unwrap();
            return match Local.from_local_datetime(&naive) {
                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
            };
        }
        "this_week" => {
            let today = Local::now().date_naive();
            let days_since_monday = today.weekday().num_days_from_monday();
            let monday = today - chrono::Duration::days(days_since_monday as i64);
            let naive = monday.and_hms_opt(0, 0, 0).unwrap();
            return match Local.from_local_datetime(&naive) {
                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
            };
        }
        "last_week" => {
            let today = Local::now().date_naive();
            let days_since_monday = today.weekday().num_days_from_monday();
            let last_monday = today - chrono::Duration::days((days_since_monday + 7) as i64);
            let naive = last_monday.and_hms_opt(0, 0, 0).unwrap();
            return match Local.from_local_datetime(&naive) {
                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
            };
        }
        _ => {}
    }

    if let Ok(parsed) = DateTime::parse_from_rfc3339(value) {
        return Ok(parsed.with_timezone(&Utc));
    }

    let local_formats = [
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%dT%H:%M",
    ];

    for format in local_formats {
        if let Ok(naive) = NaiveDateTime::parse_from_str(value, format) {
            return match Local.from_local_datetime(&naive) {
                LocalResult::Single(parsed) => Ok(parsed.with_timezone(&Utc)),
                _ => Err(Box::new(ArgumentError::InvalidDateTime(input.to_string()))),
            };
        }
    }

        } else {
            write!(f, "{} @{} (done)", self.name, self.project.name)
        }
    }
}

impl TimeEntry {
    pub fn get_description(&self) -> String {
        match self.description.as_ref() {
            "" => constants::NO_DESCRIPTION.to_string(),
            _ => self.description.to_string(),
        }
    }

    pub fn get_duration(&self) -> Duration {
        match self.stop {
            Some(_) => Duration::seconds(self.duration),
            None => Utc::now().signed_duration_since(self.start),
        }
    }

    pub fn get_duration_hmmss(&self) -> String {
        let duration = self.get_duration();
        format!(
            "{}:{:02}:{:02}",
            duration.num_hours(),
            duration.num_minutes() % 60,
            duration.num_seconds() % 60
        )
    }

    pub fn is_running(&self) -> bool {
        self.duration.is_negative()
    }

    pub fn as_running_time_entry(&self, start: DateTime<Utc>) -> TimeEntry {
        TimeEntry {
            start,
            stop: None,
            duration: -start.timestamp(),
            created_with: Some(constants::CLIENT_NAME.to_string()),
            ..self.clone()
        }
    }

    pub fn get_display_tags(&self) -> String {
        if self.tags.is_empty() {
            "".to_string()
        } else {
            format!("[{}]", self.tags.join(", "))
        }
    }
}

impl Default for TimeEntry {
    fn default() -> Self {
        let start = Utc::now();
        Self {
            id: -1,
            created_with: Some(constants::CLIENT_NAME.to_string()),
            billable: false,
            description: "".to_string(),
            duration: -start.timestamp(),
            project: None,
            start,
            stop: None,
            tags: Vec::new(),
            task: None,
            workspace_id: -1,
        }
    }
}

impl std::fmt::Display for TimeEntry {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let local_start: DateTime<Local> = self.start.with_timezone(&Local);
        let time_str = match self.stop {
            Some(stop) => {
                let local_stop: DateTime<Local> = stop.with_timezone(&Local);
                let cross_day = local_stop.date_naive() != local_start.date_naive();
                if cross_day {
                    format!(
                        "{} ~ {}",
                        local_start.format("%Y-%m-%d %H:%M"),
                        local_stop.format("%m-%d %H:%M")
                    )
                } else {
                    format!(
                        "{}~{}",
                        local_start.format("%Y-%m-%d %H:%M"),
                        local_stop.format("%H:%M")
                    )
                }
            }
            None => format!("{}~…", local_start.format("%Y-%m-%d %H:%M")),
        };
        let summary = format!(
            //{id} {date HH:MM–HH:MM} {$/space} [{duration}]{running indicator/space} – {description}{@project} {#tags}
            "{} {} {} [{}]{} –  {}{} {}",
            self.id,
            time_str,
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join(",");
        let url = format!(
            "{}/workspaces/{}/time_entries/{}",
            self.base_url, workspace_id, ids
        );
        self.patch::<Value, Value>(url, &patch).await
    }

