use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

const BILLING_UNIT_SECONDS: i64 = 15 * 60;
const MINIMUM_BILLING_SECONDS: i64 = 30 * 60;

pub struct InvoiceCommand;

#[derive(Debug, PartialEq, Eq)]
struct ProjectTotal {
    name: String,
    seconds: i64,
}

fn billed_seconds(duration: i64) -> i64 {
    let rounded =
        ((duration + BILLING_UNIT_SECONDS - 1) / BILLING_UNIT_SECONDS) * BILLING_UNIT_SECONDS;
    rounded.max(MINIMUM_BILLING_SECONDS)
}

fn project_totals(entries: impl IntoIterator<Item = TimeEntry>) -> Vec<ProjectTotal> {
    let mut totals = HashMap::<Option<i64>, ProjectTotal>::new();
    for entry in entries {
        if entry.billable && entry.stop.is_some() && entry.duration >= 0 {
            let (project_id, name) = entry
                .project
                .as_ref()
                .map(|project| (Some(project.id), project.name.clone()))
                .unwrap_or_else(|| (None, "No Project".to_string()));
            let total = totals
                .entry(project_id)
                .or_insert_with(|| ProjectTotal { name, seconds: 0 });
            total.seconds += billed_seconds(entry.duration);
        }
    }

    let mut totals: Vec<_> = totals.into_values().collect();
    totals.sort_by(|left, right| {
        right
            .seconds
            .cmp(&left.seconds)
            .then_with(|| left.name.cmp(&right.name))
    });
    totals
}

impl InvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let totals = project_totals(entries);

        if totals.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let grand_total: i64 = totals.iter().map(|total| total.seconds).sum();
        for total in totals {
            println!("{}s  {}", total.seconds, total.name);
        }
        println!("{}s  Total", grand_total);
        Ok(())
    }
}

